body.script:
// ─── Config injected from Python ────────────────────────────
var TEMPLATE_ID  = ]] ><t t-out="template.id"/><![CDATA[;
var PDF_URL      = '/sign/template/' + TEMPLATE_ID + '/pdf';
var SAVE_URL     = '/sign/template/' + TEMPLATE_ID + '/save_fields';
var SIGNER_COUNT = ]] ><t t-out="template.signer_count or 1"/><![CDATA[;
var EXISTING_FIELDS = ]] ><t t-out="fields_json"/><![CDATA[;

// ─── State ──────────────────────────────────────────────────
var pages      = [];   // { wrapper, canvas, pageNum, pageW, pageH, renderedW, renderedH }
var fields     = [];   // { id, type, page, posX, posY, width, height, required, placeholder, signerIndex, el }
var fieldIdSeq = 1;
var activeSigner  = 1;
var selectedField = null;
var draggingChip  = null;  // { type }

// ─── PDF.js config ──────────────────────────────────────────
pdfjsLib.GlobalWorkerOptions.workerSrc =
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

// ─── Signer tabs ────────────────────────────────────────────
function buildSignerTabs() {
    var tabs = document.getElementById('signerTabs');
    tabs.innerHTML = '';
    for (var i = 1; i <= SIGNER_COUNT; i++) {
        (function(idx) {
            var t = document.createElement('div');
            t.className = 'es-signer-tab' + (idx === 1 ? ' active' : '');

            var span = document.createElement('span');
            span.textContent = 'Signer ' + idx;

            var badge = document.createElement('span');
            badge.className = 'es-signer-badge';
            badge.textContent = idx;

            t.appendChild(span);
            t.appendChild(badge);

            t.dataset.idx = idx;
            t.onclick = function() { setActiveSigner(idx); };
            tabs.appendChild(t);
        })(i);
    }
}

function setActiveSigner(idx) {
    activeSigner = idx;
    document.querySelectorAll('.es-signer-tab').forEach(function(t) {
        t.classList.toggle('active', parseInt(t.dataset.idx) === idx);
    });
}

function addSigner() {
    SIGNER_COUNT++;
    buildSignerTabs();
    setActiveSigner(SIGNER_COUNT);
    if (selectedField) {
        updatePropertiesPanel();
    }
}

// ─── Field type helpers ─────────────────────────────────────
var FIELD_INFO = {
    signature: { label: '✍️ Signature', defW: 22, defH: 9 },
    initial:   { label: '🅐 Initial',   defW: 10, defH: 6 },
    name:      { label: '👤 Name',       defW: 22, defH: 5 },
    date:      { label: '📅 Date',       defW: 16, defH: 5 },
    email:     { label: '✉️ Email',      defW: 22, defH: 5 },
    text:      { label: 'Ⅰ Text',        defW: 22, defH: 5 },
    checkbox:  { label: '☐ Checkbox',   defW: 5,  defH: 5 },
};

function getLabel(f) {
    return f.placeholder || FIELD_INFO[f.type].label + ' (S' + f.signerIndex + ')';
}

// ─── Create field overlay element ───────────────────────────
function createFieldEl(f, pageWrapper) {
    var pw = pageWrapper.renderedW;
    var ph = pageWrapper.renderedH;

    var el = document.createElement('div');
    el.className = 'es-field-overlay type-' + f.type;
    el.dataset.fid = f.id;

    var lbl = document.createElement('span');
    lbl.className = 'fov-label';
    lbl.textContent = getLabel(f);
    el.appendChild(lbl);

    var del = document.createElement('span');
    del.className = 'fov-delete';
    del.textContent = '✕';
    del.onclick = function(e) { e.stopPropagation(); removeFieldById(f.id); };
    el.appendChild(del);

    var res = document.createElement('div');
    res.className = 'fov-resize';
    el.appendChild(res);

    positionEl(el, f, pw, ph);

    // Drag to move
    makeDraggable(el, f, pw, ph);
    // Resize handle
    makeResizable(res, f, pw, ph);

    el.addEventListener('click', function(e) {
        e.stopPropagation();
        selectField(f);
    });

    pageWrapper.wrapper.appendChild(el);
    f.el = el;
    return el;
}

function positionEl(el, f, pw, ph) {
    el.style.left   = (f.posX / 100 * pw) + 'px';
    el.style.top    = (f.posY / 100 * ph) + 'px';
    el.style.width  = (f.width / 100 * pw) + 'px';
    el.style.height = (f.height / 100 * ph) + 'px';
}

function elToPercent(el, f, pw, ph) {
    f.posX   = parseFloat(el.style.left)   / pw * 100;
    f.posY   = parseFloat(el.style.top)    / ph * 100;
    f.width  = parseFloat(el.style.width)  / pw * 100;
    f.height = parseFloat(el.style.height) / ph * 100;
}

// ─── Draggable overlay (move) ───────────────────────────────
function makeDraggable(el, f, pw, ph) {
    var ox, oy, sx, sy;
    el.addEventListener('mousedown', function(e) {
        if (e.target.classList.contains('fov-resize') || e.target.classList.contains('fov-delete')) return;
        e.preventDefault();
        ox = parseFloat(el.style.left);
        oy = parseFloat(el.style.top);
        sx = e.clientX; sy = e.clientY;
        function onMove(ev) {
            var nx = ox + ev.clientX - sx;
            var ny = oy + ev.clientY - sy;
            nx = Math.max(0, Math.min(pw - parseFloat(el.style.width), nx));
            ny = Math.max(0, Math.min(ph - parseFloat(el.style.height), ny));
            el.style.left = nx + 'px';
            el.style.top  = ny + 'px';
        }
        function onUp() {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            elToPercent(el, f, pw, ph);
            updatePropertiesPanel();
        }
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
    });
}

// ─── Resizable overlay ─────────────────────────────────────
function makeResizable(handle, f, pw, ph) {
    handle.addEventListener('mousedown', function(e) {
        e.preventDefault(); e.stopPropagation();
        var el = handle.parentElement;
        var sw = parseFloat(el.style.width);
        var sh = parseFloat(el.style.height);
        var sx = e.clientX; var sy = e.clientY;
        function onMove(ev) {
            var nw = Math.max(30, sw + ev.clientX - sx);
            var nh = Math.max(16, sh + ev.clientY - sy);
            el.style.width  = nw + 'px';
            el.style.height = nh + 'px';
        }
        function onUp() {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            elToPercent(el, f, pw, ph);
            updatePropertiesPanel();
        }
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
    });
}

// ─── Field selection / properties ──────────────────────────
function selectField(f) {
    if (selectedField && selectedField.el) {
        selectedField.el.classList.remove('selected');
    }
    selectedField = f;
    if (f && f.el) {
        f.el.classList.add('selected');
    }
    updatePropertiesPanel();
}

function updatePropertiesPanel() {
    var f = selectedField;
    if (!f) {
        document.getElementById('propEmpty').style.display = '';
        document.getElementById('propContent').style.display = 'none';
        return;
    }
    document.getElementById('propEmpty').style.display = 'none';
    document.getElementById('propContent').style.display = '';
    document.getElementById('propLabel').value   = f.placeholder || '';
    document.getElementById('propRequired').checked = f.required;

    // Update signer select
    var signerSelect = document.getElementById('propSignerSelect');
    signerSelect.innerHTML = '';
    for(var i=1; i<=SIGNER_COUNT; i++) {
        var opt = document.createElement('option');
        opt.value = i;
        opt.textContent = 'Signer ' + i;
        if(i === f.signerIndex) opt.selected = true;
        signerSelect.appendChild(opt);
    }
    document.getElementById('propX').value = f.posX.toFixed(1);
    document.getElementById('propY').value = f.posY.toFixed(1);
    document.getElementById('propW').value = f.width.toFixed(1);
    document.getElementById('propH').value = f.height.toFixed(1);
}

// Properties → field sync
document.getElementById('propLabel').addEventListener('input', function() {
    if (!selectedField) return;
    selectedField.placeholder = this.value;
    if (selectedField.el) selectedField.el.querySelector('.fov-label').textContent = getLabel(selectedField);
});
document.getElementById('propRequired').addEventListener('change', function() {
    if (selectedField) selectedField.required = this.checked;
});
document.getElementById('propSignerSelect').addEventListener('change', function() {
    if (selectedField) selectedField.signerIndex = parseInt(this.value);
});
['propX','propY','propW','propH'].forEach(function(id) {
    document.getElementById(id).addEventListener('change', function() {
        if (!selectedField || !selectedField.el) return;
        var pageData = pages.find(function(p) { return p.pageNum === selectedField.page; });
        if (!pageData) return;
        selectedField.posX   = parseFloat(document.getElementById('propX').value) || 0;
        selectedField.posY   = parseFloat(document.getElementById('propY').value) || 0;
        selectedField.width  = parseFloat(document.getElementById('propW').value) || 10;
        selectedField.height = parseFloat(document.getElementById('propH').value) || 5;
        positionEl(selectedField.el, selectedField, pageData.renderedW, pageData.renderedH);
    });
});

// Deselect on background click
document.getElementById('pdfArea').addEventListener('click', function(e) {
    if (e.target === this || e.target.classList.contains('es-pdf-area')) {
        selectField(null);
    }
});

// ─── Remove field ───────────────────────────────────────────
function removeFieldById(id) {
    var idx = fields.findIndex(function(f) { return f.id === id; });
    if (idx === -1) return;
    var f = fields[idx];
    if (f.el) f.el.remove();
    if (selectedField && selectedField.id === id) selectField(null);
    fields.splice(idx, 1);
}

function deleteSelectedField() {
    if (selectedField) removeFieldById(selectedField.id);
}

// ─── Add field to a page ────────────────────────────────────
function addField(type, pageNum, posX, posY) {
    var pageData = pages.find(function(p) { return p.pageNum === pageNum; });
    if (!pageData) return;
    var info = FIELD_INFO[type];
    var f = {
        id: fieldIdSeq++,
        type: type,
        page: pageNum,
        posX: posX,
        posY: posY,
        width: info.defW,
        height: info.defH,
        required: true,
        placeholder: '',
        signerIndex: activeSigner,
        el: null,
    };
    fields.push(f);
    createFieldEl(f, pageData);
    selectField(f);
}

// ─── Drag-from-chip listeners ───────────────────────────────
document.querySelectorAll('.es-field-chip').forEach(function(chip) {
    chip.addEventListener('dragstart', function(e) {
        draggingChip = { type: chip.dataset.type };
        e.dataTransfer.effectAllowed = 'copy';
    });
    chip.addEventListener('dragend', function() { draggingChip = null; });
});

function setupPageDropZone(pageData) {
    var w = pageData.wrapper;
    w.addEventListener('dragover', function(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
        w.classList.add('drag-over');
    });
    w.addEventListener('dragleave', function() { w.classList.remove('drag-over'); });
    w.addEventListener('drop', function(e) {
        e.preventDefault();
        w.classList.remove('drag-over');
        if (!draggingChip) return;
        var rect = w.getBoundingClientRect();
        var x = (e.clientX - rect.left) / pageData.renderedW * 100;
        var y = (e.clientY - rect.top)  / pageData.renderedH * 100;
        x = Math.max(0, Math.min(80, x));
        y = Math.max(0, Math.min(90, y));
        addField(draggingChip.type, pageData.pageNum, x, y);
    });
}

// ─── Load existing fields ────────────────────────────────────
function loadExistingFields() {
    if (!EXISTING_FIELDS || !EXISTING_FIELDS.length) return;
    EXISTING_FIELDS.forEach(function(fd) {
        var pageData = pages.find(function(p) { return p.pageNum === fd.page; });
        if (!pageData) return;
        var f = {
            id: fieldIdSeq++,
            type: fd.field_type,
            page: fd.page,
            posX: fd.pos_x,
            posY: fd.pos_y,
            width: fd.width,
            height: fd.height,
            required: fd.required,
            placeholder: fd.placeholder || '',
            signerIndex: fd.signer_index,
            el: null,
        };
        fields.push(f);
        createFieldEl(f, pageData);
    });
}

// ─── Render PDF ─────────────────────────────────────────────
async function renderPDF() {
    var area = document.getElementById('pdfArea');
    try {
        var loadingTask = pdfjsLib.getDocument(PDF_URL);
        var pdf = await loadingTask.promise;

        document.getElementById('loadingMsg').remove();

        for (var p = 1; p <= pdf.numPages; p++) {
            var page = await pdf.getPage(p);
            var viewport = page.getViewport({ scale: 1.4 });

            var wrapper = document.createElement('div');
            wrapper.className = 'es-page-wrapper';
            wrapper.dataset.pageNum = p;
            wrapper.style.width  = viewport.width  + 'px';
            wrapper.style.height = viewport.height + 'px';

            var numLabel = document.createElement('div');
            numLabel.className = 'es-page-num';
            numLabel.textContent = 'Page ' + p + ' of ' + pdf.numPages;

            var canvas = document.createElement('canvas');
            canvas.width  = viewport.width;
            canvas.height = viewport.height;

            wrapper.appendChild(canvas);

            var pageWrap = document.createElement('div');
            pageWrap.style.position = 'relative';
            pageWrap.appendChild(numLabel);
            pageWrap.appendChild(wrapper);
            area.appendChild(pageWrap);

            var pageData = {
                pageNum:   p,
                wrapper:   wrapper,
                canvas:    canvas,
                renderedW: viewport.width,
                renderedH: viewport.height,
            };
            pages.push(pageData);
            setupPageDropZone(pageData);
        }

        // After all wrappers are created, load fields immediately
        loadExistingFields();

        // Lazy load the actual canvas rendering
        var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                if (entry.isIntersecting) {
                    var pNum = parseInt(entry.target.dataset.pageNum);
                    observer.unobserve(entry.target);
                    pdf.getPage(pNum).then(function(page) {
                        var viewport = page.getViewport({ scale: 1.4 });
                        var ctx = entry.target.querySelector('canvas').getContext('2d');
                        page.render({ canvasContext: ctx, viewport: viewport });
                    });
                }
            });
        }, { root: area, rootMargin: '800px' });

        document.querySelectorAll('.es-page-wrapper').forEach(function(el) {
            observer.observe(el);
        });

    } catch (err) {
        document.getElementById('loadingMsg').innerHTML = '<span style="color:#ef4444;">Failed to load PDF: ' + err.message + '</span>';
    }
}

// ─── Save fields to backend ─────────────────────────────────
async function saveFields() {
    var btn = document.getElementById('btnSave');
    btn.disabled = true;
    btn.textContent = '⏳ Saving…';

    var payload = fields.map(function(f) {
        return {
            field_type:   f.type,
            page:         f.page,
            pos_x:        parseFloat(f.posX.toFixed(2)),
            pos_y:        parseFloat(f.posY.toFixed(2)),
            width:        parseFloat(f.width.toFixed(2)),
            height:       parseFloat(f.height.toFixed(2)),
            required:     f.required,
            placeholder:  f.placeholder,
            signer_index: f.signerIndex,
        };
    });

    try {
        var resp = await fetch(SAVE_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { fields_data: payload, signer_count: SIGNER_COUNT } }),
        });
        var data = await resp.json();
        if (data.result && data.result.success) {
            var status = document.getElementById('saveStatus');
            status.style.display = 'inline';
            setTimeout(function() { status.style.display = 'none'; }, 3000);
        } else {
            alert('Save failed: ' + JSON.stringify(data.error || data.result));
        }
    } catch (e) {
        alert('Error saving: ' + e.message);
    } finally {
        btn.disabled = false;
        btn.textContent = '💾 Save Fields';
    }
}

// ─── Init ────────────────────────────────────────────────────
buildSignerTabs();
renderPDF();
